$f_f04122bab9 = static function ($val, $inv, $conv) {
    $a = Perl::split('/,?\s+/', $val, 0);
    if ($inv) {
        $invConv = [];
        foreach (array_keys($conv) as $_) {
            $invConv[strtolower(Perl::str($conv[$_]))] = $_;
        }
        if (count($a) == 1) {
            preg_match_all('/(Y|Cb|Cr|R|G|B)/', $a[0], $m);
            $a = $m[1];
        }
        foreach ($a as &$_) {
            $_ = $invConv[strtolower($_)] ?? null;
            if ($_ === null) {
                return null;
            }
        }
        unset($_);
        while (count($a) < 4) {
            $a[] = 0;
        }
    } else {
        foreach ($a as &$_) {
            $_ = ($conv[$_] ?? null) ?: 'Err (' . $_ . ')';
        }
        unset($_);
    }
    return implode(', ', $a);
};
